 float OriginalPair12Tilt(float time){PetalArtMotion(new Vector4(0,0,1,0),time,2*Mathf.PI*2/layers[1].petals.Length,1,2,out float tilt,out _,0);return tilt;}
 internal void VerifyPair12Envelope(){
  Directory.CreateDirectory("Outputs/Pair12");SetBloomProgress(1);EnsureArtLooks();LoadFlexCandidate();SetArtPreviewImmediate(FlowerArtState.Wandering);VerifyPair10Envelope();
  float centre=artLooks[2].droop*.7f,a=Mathf.Abs(artProfiles[2].amplitude),lo=centre+Pair12TiltBias-a*Pair12BreathScale,hi=centre+Pair12TiltBias+a*Pair12BreathScale;
  var domain=flexData.nodes[0];if(Mathf.Min(centre-a,lo)<domain.min.z-1e-6f||Mathf.Max(centre+a,hi)>domain.max.z+1e-6f)throw new Exception("P2 exceeds independent baked flex domain");
  var scan=new FlowerSurfaceCollision(this);var hits=new List<FlowerSurfaceCollision.Contact>();var p1=new Vector3[BottomSurface];var p2=new Vector3[BottomSurface];var w1=new Vector3[BottomSurface];var w2=new Vector3[BottomSurface];SampleDiagnosticSurface(1,1,1,p1);SampleDiagnosticSurface(1,2,1,p2);
  for(int x=0;x<=32;x++)for(int y=0;y<=32;y++){var m1=Pair10ValidationMatrix(1,Pair10TiltBias+Pair10BreathScale*(-4+x*.25f),OpenRoll(1,1)+Pair10RollBias);var m2=OpenMatrix(1,2,1,centre+Pair12TiltBias+Pair12BreathScale*(-4+y*.25f),OpenRoll(1,2));for(int k=0;k<BottomSurface;k++){w1[k]=m1.MultiplyPoint3x4(p1[k]);w2[k]=m2.MultiplyPoint3x4(p2[k]);}scan.SamplePetalPositions(8,w1);scan.SamplePetalPositions(9,w2);scan.FindPairContacts(8,9,hits);if(hits.Exists(h=>h.lengthA>=.25f&&h.lengthB>=.25f))throw new Exception("Pair12 envelope contact "+x+","+y);}
  File.WriteAllText("Outputs/Pair12/Envelope.txt","PASS: 33 x 33 independent breathing combinations on P1/P2; earlier P0/P1 envelope retained.");File.WriteAllText("Outputs/Pair12/FlexDomain.txt","PASS: P2 range ["+lo+","+hi+"] and every bloom-gated intermediate remain in independently baked z interval ["+domain.min.z+","+domain.max.z+"]. Baker uses z as actual P2 tilt; numerical producer unchanged.");
 }
 internal void VerifyPair12(){
  Directory.CreateDirectory("Outputs/Pair12");SetBloomProgress(1);EnsureArtLooks();LoadFlexCandidate();SetArtPreviewImmediate(FlowerArtState.Wandering);var scan=new FlowerSurfaceCollision(this);var hits=new List<FlowerSurfaceCollision.Contact>();var petals=scan.Petals;var local=new Vector3[PetalCount][];var world=new Vector3[PetalCount][];for(int p=0;p<PetalCount;p++){local[p]=new Vector3[BottomSurface];world[p]=new Vector3[BottomSurface];SampleDiagnosticSurface(petals[p].layer,petals[p].index,1,local[p]);}
  void Pose(int p,float time,bool candidate){var item=petals[p];PetalArtMotion(new Vector4(0,0,1,0),time,item.index*Mathf.PI*2/layers[item.layer].petals.Length,item.layer,item.index,out float tilt,out float roll);if(p==9&&!candidate)tilt=OriginalPair12Tilt(time);if(p==10){artTime=time;var parameter=FlexParameter();if(!candidate)parameter.z=OriginalPair12Tilt(time);QueryFlex(flexData,parameter,flexField.controls,out tilt);}var m=p==1?Pair01ValidationMatrix(1,tilt,roll):p==5?Pair55ValidationMatrix(1,tilt,roll):p==14?Pair20ValidationMatrix(1,tilt,roll):p==17?Pair24ValidationMatrix(1,tilt,roll):p==8?Pair10ValidationMatrix(1,tilt,roll):OpenMatrix(item.layer,item.index,1,tilt,roll);if(candidate&&(p==9||p==10)){var l=layers[1];var petal=l.petals[item.index];PathPetalPose(l,petal,item.index,1,out var position,out var rotation,out var scale);ApplyPetalPose(l,petal,item.index,position,rotation*Quaternion.Euler(tilt,0,roll),scale);m=generated.worldToLocalMatrix*petal.body.localToWorldMatrix;}for(int k=0;k<BottomSurface;k++)world[p][k]=m.MultiplyPoint3x4(local[p][k]+(p==10?flexData.normals[k]*flexField.Height(k):Vector3.zero));scan.SamplePetalPositions(p,world[p]);}
  bool Contact(int a,int b){scan.FindPairContacts(Mathf.Min(a,b),Mathf.Max(a,b),hits);return hits.Exists(h=>h.lengthA>=.25f&&h.lengthB>=.25f);}
  int failures=0;var report=new List<string>{"time,baselineTarget,candidateTarget"};
  for(int step=0;step<=1200;step++){float time=step*.1f;for(int p=0;p<PetalCount;p++)Pose(p,time,false);var old9=new HashSet<int>();var old10=new HashSet<int>();for(int o=0;o<PetalCount;o++){if(o!=9&&Contact(9,o))old9.Add(o);if(o!=10&&Contact(10,o))old10.Add(o);}if(old9.Contains(8))failures++;report.Add(time+","+old9.Contains(8)+",false");Pose(9,time,true);Pose(10,time,true);if(Contact(8,9)||Contact(7,8)||Contact(0,1)||Contact(2,3)||Contact(5,12)||Contact(13,14)||Contact(13,17))throw new Exception("Pair12 regression at "+time);for(int o=0;o<PetalCount;o++){if(o!=9&&Contact(9,o)&&!old9.Contains(o))throw new Exception("New P2 contact 9:"+o+" at "+time);if(o!=10&&Contact(10,o)&&!old10.Contains(o))throw new Exception("New dependent P3 contact 10:"+o+" at "+time);}foreach(int other in FlexNeighbours){scan.FindPairContacts(Mathf.Min(other,10),Mathf.Max(other,10),hits);if(hits.Exists(h=>(other<10?h.lengthB:h.lengthA)>=.25f&&(other==3||(other<10?h.lengthA:h.lengthB)>=.25f)))throw new Exception("Dependent P3 constrained contact "+other+" at "+time);}if(step%100==0)Debug.Log("PAIR12_VERIFIED "+time);}
  File.WriteAllLines("Outputs/Pair12/Timeline.csv",report);File.WriteAllText("Outputs/Pair12/Result.txt","PASS: 1201 actual-pose/lookup samples across 120 seconds. P1/P2 clear, previous six pairs retained, no added P2 or dependent P3 contacts. Baseline target failures="+failures);
 }
 internal void VerifyPair12Transitions(){
  Directory.CreateDirectory("Outputs/Pair12");LoadFlexCandidate();var scan=new FlowerSurfaceCollision(this);var hits=new List<FlowerSurfaceCollision.Contact>();var local2=new Vector3[BottomSurface];var local3=new Vector3[BottomSurface];var world2=new Vector3[BottomSurface];var world3=new Vector3[BottomSurface];var oldField=new FlexField();int count=0;
  HashSet<int> Contacts(){var result=new HashSet<int>();foreach(int p in new[]{9,10})for(int o=0;o<PetalCount;o++)if(o!=p){scan.FindPairContacts(Mathf.Min(p,o),Mathf.Max(p,o),hits);if(hits.Exists(h=>h.lengthA>=.25f&&h.lengthB>=.25f))result.Add(Mathf.Min(p,o)*PetalCount+Mathf.Max(p,o));}return result;}
  foreach(var state in new[]{FlowerArtState.Clarity,FlowerArtState.Gathering,FlowerArtState.Quiet})foreach(bool entering in new[]{true,false}){
   SetArtPreviewImmediate(entering?state:FlowerArtState.Wandering);SetArtState(entering?FlowerArtState.Wandering:state);
   for(int step=0;step<=120;step++){MotionStep(.05f);scan.SampleRendered();var candidate=Contacts();float az=2*Mathf.PI*2/6;PetalArtMotion(ArtWeights,artTime,az,1,2,out float tilt2,out float roll2);float wave=OriginalPair12Tilt(artTime)-artLooks[2].droop*.7f;tilt2-=ArtWeights.z*Pair12MotionGate(ArtWeights.z)*(Pair12TiltBias+(Pair12BreathScale-1)*wave);PetalArtMotion(ArtWeights,artTime,3*Mathf.PI*2/6,1,3,out float tilt3,out float roll3);var parameter=FlexParameter();parameter.z=OriginalPair12Tilt(artTime);QueryFlex(flexData,parameter,oldField.controls,out float corrected);tilt3+=flexWeight*(corrected-parameter.y);SampleDiagnosticSurface(1,2,bloomProgress,local2);SampleDiagnosticSurface(1,3,bloomProgress,local3);var m2=generated.localToWorldMatrix*OpenMatrix(1,2,bloomProgress,tilt2,roll2);var m3=generated.localToWorldMatrix*OpenMatrix(1,3,bloomProgress,tilt3,roll3);for(int k=0;k<BottomSurface;k++){world2[k]=m2.MultiplyPoint3x4(local2[k]);world3[k]=m3.MultiplyPoint3x4(local3[k]+flexData.normals[k]*(oldField.Height(k)*flexWeight));}scan.SamplePetalPositions(9,world2);scan.SamplePetalPositions(10,world3);var baseline=Contacts();foreach(int pair in candidate)if(!baseline.Contains(pair))throw new Exception("New transition contact "+(pair/PetalCount)+":"+(pair%PetalCount)+" state="+state+" entering="+entering+" time="+artTime);if(RootAnchorError()>1e-5f)throw new Exception("Root drift");count++;}
  }
  SetArtPreviewImmediate(FlowerArtState.Wandering);MotionStep(10);var held2=layers[1].petals[2].body.localToWorldMatrix;var held3=layers[1].petals[3].body.localToWorldMatrix;float clock=artTime;var controls=(float[])flexField.controls.Clone();SetFrozen(true);for(int i=0;i<30;i++)MotionStep(.1f);if(artTime!=clock||held2!=layers[1].petals[2].body.localToWorldMatrix||held3!=layers[1].petals[3].body.localToWorldMatrix)throw new Exception("Frozen pose moved");for(int i=0;i<controls.Length;i++)if(controls[i]!=flexField.controls[i])throw new Exception("Frozen flex moved");SetFrozen(false);MotionStep(.1f);if(artTime<=clock||RootAnchorError()>1e-5f)throw new Exception("Resume failed");File.WriteAllText("Outputs/Pair12/Transitions.txt","PASS: "+count+" samples at 0.05 s across six transition directions. No new P2/dependent P3 contacts; roots, frozen transforms/controls and resume verified.");
 }
 internal void CapturePair12(){
  if(!UsesGpuPlayback)throw new Exception("Review requires formal GPU playback");Directory.CreateDirectory("Outputs/Pair12");Directory.CreateDirectory("Outputs/WanderFollow");SetArtPreviewImmediate(FlowerArtState.Wandering);VerifyOuterGpuFlex();var gallery=FindObjectOfType<FlowerGallery>();gallery.enabled=false;gallery.showInterface=false;var labels=new GameObject("Pair12 review labels");foreach(int index in new[]{1,2}){var item=new GameObject("L1-P"+index);item.transform.SetParent(labels.transform);var text=item.AddComponent<TextMesh>();text.text=item.name;text.fontSize=48;text.characterSize=.045f;text.anchor=TextAnchor.MiddleCenter;text.color=Color.yellow;}
  void Shot(string name){foreach(Transform child in labels.transform){int index=child.name.EndsWith("1")?1:2;var p=layers[1].petals[index];child.position=p.body.TransformPoint(PetalMesh(1,index).vertices[48*129+64])+Camera.main.transform.up*.05f;child.rotation=Camera.main.transform.rotation;}WanderFollowPreview.Shot(name);File.Copy("Outputs/WanderFollow/"+name+".png","Outputs/Pair12/"+name+".png",true);}
  float failureTime=0;foreach(string line in File.ReadAllLines("Outputs/Pair12/Timeline.csv")){if(!line.Contains(",True,"))continue;failureTime=float.Parse(line.Split(',')[0],System.Globalization.CultureInfo.InvariantCulture);break;}
  foreach(var view in new[]{new Vector2(22,55),new Vector2(0,90),new Vector2(22,8)}){SetArtPreviewImmediate(FlowerArtState.Wandering);MotionStep(failureTime);gallery.SetView(view.x,view.y);string suffix=view.y.ToString("F0");Shot("After"+suffix);var l=layers[1];var p=l.petals[2];PathPetalPose(l,p,2,1,out var position,out var rotation,out var scale);ApplyPetalPose(l,p,2,position,rotation*Quaternion.Euler(OriginalPair12Tilt(artTime),0,OpenRoll(1,2)),scale);var parameter=FlexParameter();parameter.z=OriginalPair12Tilt(artTime);QueryFlex(flexData,parameter,flexField.controls,out float tilt3);p=l.petals[3];PathPetalPose(l,p,3,1,out position,out rotation,out scale);ApplyPetalPose(l,p,3,position,rotation*Quaternion.Euler(tilt3,0,OpenRoll(1,3)),scale);FinishFlex();Shot("Before"+suffix);}
  SetArtPreviewImmediate(FlowerArtState.Wandering);gallery.SetView(22,55);for(int frame=0;frame<120;frame++){MotionStep(.1f);Shot("Frame"+frame.ToString("D3"));}SetArtPreviewImmediate(FlowerArtState.Wandering);MotionStep(failureTime);SoloPetal(1,1);SetPetalVisible(1,2,true);int number=1;foreach(var view in new[]{new Vector2(22,55),new Vector2(0,90),new Vector2(22,8)}){gallery.SetView(view.x,view.y,7);Shot("Close"+number.ToString("D2"));number++;}ShowAllPetals();DestroyImmediate(labels);File.WriteAllText("Outputs/Pair12/Review.txt","PASS: formal GPU before/after at a proven failure time, 120 preview frames and 3 numbered close views. Before view restores both original P2 motion and its dependent P3 lookup.");
 }
